package com.hospital.mes.reporting.domain;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;
import java.math.*;
import java.time.*;
import org.erdtman.jcs.JsonCanonicalizer;

/** Strict persisted configuration projection, independent of business labels and database identities. */
public final class PrintSourceConfiguration {
 private PrintSourceConfiguration(){}
 public static String text(JsonNode n,String key,int max){var v=n.get(key);if(v==null||!v.isTextual()||v.asText().isBlank()||v.asText().length()>max)throw new IllegalArgumentException("Invalid "+key);return v.asText();}
 public static void shape(JsonNode n,String... allowed){if(n==null||!n.isObject())throw new IllegalArgumentException("Object required");var names=Set.of(allowed);n.fieldNames().forEachRemaining(k->{if(!names.contains(k))throw new IllegalArgumentException("Unknown field: "+k);});}
 public static void key(String value,String regex){if(!value.matches(regex))throw new IllegalArgumentException("Invalid identifier: "+value);}
 public static List<String> types(JsonNode n){if(n==null||!n.isArray()||n.size()>200)throw new IllegalArgumentException("Invalid businessTypes");var out=new TreeSet<String>();for(var v:n){if(!v.isTextual())throw new IllegalArgumentException("Business type must be a string");key(v.asText(),"[A-Za-z][A-Za-z0-9_]{0,79}");if(!out.add(v.asText()))throw new IllegalArgumentException("Duplicate business type");}return List.copyOf(out);}
 public static ArrayNode sort(JsonNode n,String order,String id){var list=new ArrayList<JsonNode>();n.forEach(list::add);list.sort(Comparator.comparingInt((JsonNode v)->v.path(order).asInt()).thenComparing(v->v.path(id).asText()));var a=JsonNodeFactory.instance.arrayNode();list.forEach(a::add);return a;}
 public static ObjectNode normalize(JsonNode input){
  shape(input,"schemaVersion","sourceName","mainCatalogId","parameterDeclarations","joins","fields");
  if(!input.path("schemaVersion").isIntegralNumber()||input.path("schemaVersion").asInt()!=1)throw new IllegalArgumentException("Unsupported schemaVersion");
  text(input,"sourceName",120);key(text(input,"mainCatalogId",80),"[A-Za-z][A-Za-z0-9_.-]{0,79}");
  var n=(ObjectNode)input.deepCopy();var parameters=n.path("parameterDeclarations");
  if(!parameters.isArray()||parameters.isEmpty()||parameters.size()>4)throw new IllegalArgumentException("Invalid parameter declarations");
  var parameterNames=new HashSet<String>();boolean document=false;
  for(var p:parameters){shape(p,"name","source","contextKey");var name=text(p,"name",80);key(name,"[A-Za-z][A-Za-z0-9_]{0,79}");if(!parameterNames.add(name))throw new IllegalArgumentException("Duplicate parameter");var source=text(p,"source",20);if(source.equals("DOCUMENT_ID")){if(p.hasNonNull("contextKey"))throw new IllegalArgumentException("Document parameter has no contextKey");document=true;}else if(!source.equals("SERVER_CONTEXT")||!Set.of("ORG_ID","ACTOR_ID").contains(p.path("contextKey").asText()))throw new IllegalArgumentException("Unsupported server context");}
  if(!document)throw new IllegalArgumentException("DOCUMENT_ID required");
  var joins=n.path("joins");var fields=n.path("fields");if(!joins.isArray()||joins.size()>12||!fields.isArray()||fields.isEmpty()||fields.size()>200)throw new IllegalArgumentException("Invalid configuration limits");
  var nodes=new HashMap<String,JsonNode>();var datasets=new HashSet<String>();
  for(var j:joins){shape(j,"nodeId","label","parentNodeId","catalogId","knownRelationId","cardinality","keys","sort","displayOrder","datasetKey");var node=text(j,"nodeId",80);key(node,"[A-Za-z][A-Za-z0-9_]{0,79}");if(node.equals("main")||nodes.put(node,j)!=null)throw new IllegalArgumentException("Duplicate nodeId");text(j,"label",120);text(j,"parentNodeId",80);text(j,"catalogId",80);text(j,"knownRelationId",80);order(j);var kind=text(j,"cardinality",3);if(!Set.of("1:1","N:1","1:N").contains(kind))throw new IllegalArgumentException("Invalid cardinality");
   var keys=j.path("keys");if(!keys.isArray()||keys.isEmpty()||keys.size()>4)throw new IllegalArgumentException("Invalid join keys");for(var k:keys){shape(k,"parentFieldId","targetFieldId");text(k,"parentFieldId",80);text(k,"targetFieldId",80);}
   var obj=(ObjectNode)j;if(!obj.has("sort"))obj.set("sort",JsonNodeFactory.instance.arrayNode());if(!obj.has("datasetKey"))obj.putNull("datasetKey");
   if(!j.path("sort").isArray()||j.path("sort").size()>8)throw new IllegalArgumentException("Invalid sorting");for(var s:j.path("sort")){shape(s,"catalogFieldId","direction");text(s,"catalogFieldId",80);if(!Set.of("ASC","DESC").contains(s.path("direction").asText()))throw new IllegalArgumentException("Invalid sort direction");}
   if(kind.equals("1:N")){var d=text(j,"datasetKey",80);key(d,"[A-Za-z][A-Za-z0-9]{0,79}");if(!datasets.add(d))throw new IllegalArgumentException("Duplicate datasetKey");}else if(j.hasNonNull("datasetKey"))throw new IllegalArgumentException("Single relation cannot define a dataset");
  }
  var groups=new HashMap<String,String>();groups.put("main",null);
  for(var name:nodes.keySet()){var seen=new HashSet<String>();var current=name;String group=null;int depth=0;while(!current.equals("main")){if(!seen.add(current)||++depth>4||!nodes.containsKey(current))throw new IllegalArgumentException("Cyclic, missing or too deep relation");var j=nodes.get(current);if(j.path("cardinality").asText().equals("1:N")){if(group!=null)throw new IllegalArgumentException("Nested collections unsupported");group=j.path("datasetKey").asText();}current=j.path("parentNodeId").asText();}groups.put(name,group);}
  var ids=new HashSet<String>();var keys=new HashSet<String>();
  for(var f:fields){shape(f,"fieldId","fieldKey","label","dataType","sourcePath","dataGroup","datasetKey","available","format","missing","defaultValue","displayOrder");var id=text(f,"fieldId",80);key(id,"[A-Za-z][A-Za-z0-9_-]{0,79}");var k=text(f,"fieldKey",80);key(k,"[A-Za-z][A-Za-z0-9]{0,79}");if(!ids.add(id)||!keys.add(k)||datasets.contains(k))throw new IllegalArgumentException("Duplicate or dataset-colliding field key");text(f,"label",120);order(f);var type=text(f,"dataType",10);if(!Set.of("TEXT","NUMBER","DATE","DATETIME","BOOLEAN").contains(type))throw new IllegalArgumentException("Invalid dataType");shape(f.path("sourcePath"),"nodeId","catalogFieldId");var node=text(f.path("sourcePath"),"nodeId",80);text(f.path("sourcePath"),"catalogFieldId",80);if(!groups.containsKey(node))throw new IllegalArgumentException("Unknown source node");var obj=(ObjectNode)f;
   if(!obj.has("datasetKey"))obj.putNull("datasetKey");if(!obj.has("dataGroup"))obj.put("dataGroup","MAIN");if(!obj.has("available"))obj.put("available",true);if(!obj.path("available").isBoolean())throw new IllegalArgumentException("available must be boolean");
   String dataset=obj.hasNonNull("datasetKey")?obj.path("datasetKey").asText():null;if(!Objects.equals(groups.get(node),dataset)||!obj.path("dataGroup").asText().equals(dataset==null?"MAIN":dataset))throw new IllegalArgumentException("Dataset membership mismatch");
   if(!obj.has("format"))obj.set("format",JsonNodeFactory.instance.objectNode().put("kind","RAW").putNull("scale").putNull("roundingMode").putNull("dateStyle"));
   var format=obj.path("format");shape(format,"kind","scale","roundingMode","dateStyle");for(var required:List.of("kind","scale","roundingMode","dateStyle"))if(!format.has(required))throw new IllegalArgumentException("Missing format property");var mode=format.path("kind").asText();
   if(mode.equals("RAW")){if(format.hasNonNull("scale")||format.hasNonNull("roundingMode")||format.hasNonNull("dateStyle"))throw new IllegalArgumentException("RAW has no formatting options");}
   else if(mode.equals("NUMBER")){if(!type.equals("NUMBER")||!format.path("scale").isIntegralNumber()||format.path("scale").asInt()<0||format.path("scale").asInt()>6||!format.path("roundingMode").asText().equals("HALF_UP")||format.hasNonNull("dateStyle"))throw new IllegalArgumentException("Invalid number display format");}
   else if(mode.equals("DATE")){if(!Set.of("DATE","DATETIME").contains(type)||!Set.of("DATE_ONLY","UTC_DATE_TIME").contains(format.path("dateStyle").asText())||format.hasNonNull("scale")||format.hasNonNull("roundingMode"))throw new IllegalArgumentException("Invalid date display format");}else throw new IllegalArgumentException("Unsupported format");
   if(!obj.has("missing"))obj.put("missing","ERROR");if(!obj.has("defaultValue"))obj.putNull("defaultValue");var missing=obj.path("missing").asText();if(!Set.of("ERROR","EMPTY","DEFAULT").contains(missing))throw new IllegalArgumentException("Invalid missing mode");if(missing.equals("DEFAULT")){validateValue(type,obj.path("defaultValue"));}else if(obj.hasNonNull("defaultValue"))throw new IllegalArgumentException("Default requires DEFAULT missing mode");
  }
  n.set("joins",sort(joins,"displayOrder","nodeId"));n.set("fields",sort(fields,"displayOrder","fieldId"));return n;
 }
 private static void order(JsonNode n){if(!n.path("displayOrder").isIntegralNumber()||n.path("displayOrder").asLong()<0||n.path("displayOrder").asLong()>Integer.MAX_VALUE)throw new IllegalArgumentException("displayOrder required");}
 public static void validateValue(String type,JsonNode value){if(value==null||value.isNull())throw new IllegalArgumentException("Default value required");if(type.equals("BOOLEAN")){if(!value.isBoolean())throw new IllegalArgumentException("Boolean required");return;}if(!value.isTextual()||value.asText().length()>1000)throw new IllegalArgumentException("String value required");String v=value.asText();if(type.equals("NUMBER")){if(!v.matches("-?(?:0|[1-9][0-9]*)(?:\\.[0-9]{1,6})?"))throw new IllegalArgumentException("Exact decimal string required");new BigDecimal(v);}if(type.equals("DATE"))LocalDate.parse(v);if(type.equals("DATETIME"))Instant.parse(v);}
 public static Object raw(Object value,String type){if(value==null)return null;return switch(type){case "NUMBER"->new BigDecimal(value.toString()).toPlainString();case "BOOLEAN"->value instanceof Boolean?value:value instanceof Number number?number.intValue()!=0:Boolean.valueOf(value.toString());case "DATE"->value instanceof java.sql.Date d?d.toLocalDate().toString():value.toString();case "DATETIME"->value instanceof java.sql.Timestamp t?t.toLocalDateTime().toInstant(ZoneOffset.UTC).toString():value.toString();default->value.toString();};}
 public static Object display(Object value,JsonNode f){Object raw=raw(value,f.path("dataType").asText());if(raw==null){String missing=f.path("missing").asText();if(missing.equals("ERROR"))throw new com.hospital.mes.common.exception.ComplianceException("PRINT_SOURCE_MISSING_VALUE","缺失字段："+f.path("label").asText());if(missing.equals("EMPTY"))return "";raw=f.path("defaultValue").isBoolean()?f.path("defaultValue").asBoolean():f.path("defaultValue").asText();}var format=f.path("format");return switch(format.path("kind").asText()){case "NUMBER"->new BigDecimal(raw.toString()).setScale(format.path("scale").asInt(),RoundingMode.HALF_UP).toPlainString();case "DATE"->format.path("dateStyle").asText().equals("DATE_ONLY")?raw.toString().substring(0,10):(raw.toString().length()==10?LocalDate.parse(raw.toString()).atStartOfDay().toInstant(ZoneOffset.UTC).toString():Instant.parse(raw.toString()).toString());default->raw;};}
 public static String canonical(Object value,ObjectMapper json){try{return new JsonCanonicalizer(json.writeValueAsBytes(value)).getEncodedString();}catch(Exception e){throw new IllegalArgumentException("Invalid canonical value",e);}}
 public static String hash(Object value,ObjectMapper json){return com.hospital.mes.reporting.application.PrintService.hash(canonical(value,json).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
}
